function maxScore(n, k, stayScore, travelScore):
    // dp[j] represents the maximum score achievable ending at city j after the previous day
    dp = array of size n initialized to 0

    for day from 0 to k-1:
        // Initialize new_dp with the "Stay" option:
        // If we were at city j yesterday, staying gives dp[j] + stayScore[day][j]
        new_dp = array of size n
        for j from 0 to n-1:
            new_dp[j] = dp[j] + stayScore[day][j]

        // Evaluate the "Move" option:
        // Try moving from every possible previous city p to every possible current city j
        for p from 0 to n-1:
            prev_score = dp[p]
            for j from 0 to n-1:
                move_score = prev_score + travelScore[p][j]
                if move_score > new_dp[j]:
                    new_dp[j] = move_score

        // Update dp state for the next iteration
        dp = new_dp

    return the maximum value in dp

