function max_factor_score(nums):
    n = length(nums)
    max_score = 0

    // Helper to compute GCD of a list
    function compute_gcd(arr):
        if arr is empty: return 0
        result = arr[0]
        for x in arr[1:]:
            result = gcd(result, x)
        return result

    // Helper to compute LCM of a list
    function compute_lcm(arr):
        if arr is empty: return 0
        result = arr[0]
        for x in arr[1:]:
            result = (result * x) // gcd(result, x)
        return result

    // Helper to compute factor score
    function compute_score(arr):
        if arr is empty: return 0
        return compute_gcd(arr) * compute_lcm(arr)

    // Option 1: No removal
    max_score = max(max_score, compute_score(nums))

    // Option 2: Remove exactly one element
    for i from 0 to n-1:
        temp = nums without element at index i
        score = compute_score(temp)
        max_score = max(max_score, score)

    return max_score

