function findAnswer(parent, s):
    n = length(parent)
    adj = adjacency list from parent array
    for each node u in 0..n-1:
        sort adj[u] in increasing order

    // Precompute powers for rolling hash
    MOD1 = 10^9 + 7, BASE1 = 31
    MOD2 = 10^9 + 9, BASE2 = 37
    pow1, pow2 = precompute powers up to n

    // Determine processing order: children before parents (reverse topological)
    stack = [0], order = []
    while stack not empty:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            stack.push(v)
    reverse(order)

    sz = array of size n
    h1, h1r, h2, h2r = arrays of size n
    char_vals = [ord(c) - 'a' + 1 for c in s]

    for u in order:
        children = adj[u]
        total_sz_children = sum(sz[v] for v in children)
        sz[u] = 1 + total_sz_children

        // Forward hash: H(u) = (...((H(c1)*B^sz[c2] + H(c2))...)*B^sz[ck] + H(ck)) * B + s[u]
        val1 = 0
        for v in children:
            val1 = (val1 * pow1[sz[v]] + h1[v]) % MOD1
        h1[u] = (val1 * BASE1 + char_vals[u]) % MOD1

        // Reverse hash: H_rev(u) = s[u]*B^total + (...((H_rev(ck)*B^sz[c(k-1)] + H_rev(c(k-1)))...))
        val1r = 0
        for v in reversed(children):
            val1r = (val1r * pow1[sz[v]] + h1r[v]) % MOD1
        h1r[u] = (char_vals[u] * pow1[total_sz_children] + val1r) % MOD1

        // Repeat for second hash pair (MOD2, BASE2)
        val2 = 0
        for v in children:
            val2 = (val2 * pow2[sz[v]] + h2[v]) % MOD2
        h2[u] = (val2 * BASE2 + char_vals[u]) % MOD2

        val2r = 0
        for v in reversed(children):
            val2r = (val2r * pow2[sz[v]] + h2r[v]) % MOD2
        h2r[u] = (char_vals[u] * pow2[total_sz_children] + val2r) % MOD2

        // Palindrome check: forward hash equals reverse hash
        ans[u] = (h1[u] == h1r[u] and h2[u] == h2r[u])

    return ans

