function findXSum(nums, k, x):
    n = length of nums
    answer = empty list

    for i from 0 to n - k:
        subarray = nums[i] to nums[i + k - 1]

        // Count frequencies of each element in the subarray
        counts = empty map
        for val in subarray:
            counts[val] = counts[val] + 1

        // Create list of (value, frequency) pairs
        items = list of (val, freq) from counts

        // Sort by frequency descending, then by value descending
        sort items using key: (-frequency, -value)

        // Select top x distinct values (or all if fewer than x)
        top_x_count = min(x, length of items)
        top_x_values = empty set
        for j from 0 to top_x_count - 1:
            add items[j].value to top_x_values

        // Calculate sum of elements in subarray that are in top_x_values
        current_sum = 0
        for val in subarray:
            if val is in top_x_values:
                current_sum = current_sum + val

        append current_sum to answer

    return answer

