function hasIncreasingSubarrays(nums, k):
    n = length(nums)
    max_start_index = n - 2 * k

    for i from 0 to max_start_index:
        // Check if first subarray starting at i is strictly increasing
        is_first_increasing = true
        for j from 0 to k - 2:
            if nums[i + j] >= nums[i + j + 1]:
                is_first_increasing = false
                break

        if not is_first_increasing:
            continue

        // Check if second subarray starting at i + k is strictly increasing
        is_second_increasing = true
        for j from 0 to k - 2:
            if nums[i + k + j] >= nums[i + k + j + 1]:
                is_second_increasing = false
                break

        if is_second_increasing:
            return true

    return false

