function countPossibleOriginalStrings(word):
    if word is empty:
        return 0

    // Start with 1 for the case where no error occurred
    total_count = 1

    // Initialize tracking for the current block of identical characters
    current_block_length = 1

    // Iterate through the string starting from the second character
    for i from 1 to length(word) - 1:
        if word[i] equals word[i-1]:
            // Extend the current block
            current_block_length += 1
        else:
            // Block ended: add possibilities for this block
            // If block length is L, there are L-1 ways it could have been shortened
            total_count += (current_block_length - 1)
            // Reset for the next block
            current_block_length = 1

    // Add possibilities for the final block
    total_count += (current_block_length - 1)

    return total_count

