function maxFrequency(nums, k, numOperations):
    sort nums
    n = length(nums)
    ans = 0

    // Step 1: Iterate over each unique value v in nums as a potential target
    i = 0
    while i < n:
        v = nums[i]

        // Find count of elements equal to v (C_eq)
        R_eq = bisect_right(nums, v)
        C_eq = R_eq - i

        // Find range [v-k, v+k] using two pointers
        while nums[L] < v - k:
            L += 1
        while nums[R] <= v + k:
            R += 1
        C_range = R - L

        // Calculate max frequency if target is v
        current_ans = min(C_range, C_eq + numOperations)
        ans = max(ans, current_ans)

        i = R_eq

    // Step 2: Check if optimal target is not in nums (max interval overlap)
    events = []
    for x in nums:
        events.append((x - k, +1))
        events.append((x + k + 1, -1))

    sort events by coordinate
    curr_overlap = 0
    M = 0
    for _, type_ in events:
        curr_overlap += type_
        M = max(M, curr_overlap)

    // If target not in nums, we can only use numOperations
    candidate = min(M, numOperations)
    ans = max(ans, candidate)

    return ans

