function minTimeToReach(moveTime):
    n = number of rows in moveTime
    m = number of columns in moveTime

    // Priority queue stores (current_time, row, col), ordered by current_time
    pq = min-heap containing (0, 0, 0)

    // Distance matrix to store minimum arrival time for each cell
    dist = 2D array of size n x m initialized to infinity
    dist[0][0] = 0

    while pq is not empty:
        t, r, c = pop smallest element from pq

        // If destination reached, return time
        if r == n - 1 and c == m - 1:
            return t

        // Skip if we found a faster path to this cell already
        if t > dist[r][c]:
            continue

        for each direction (dr, dc) in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr = r + dr
            nc = c + dc

            if nr and nc are within grid boundaries:
                // Determine when we can start moving to neighbor
                // Must wait until current time t OR the room's start constraint
                start_time = max(t, moveTime[nr][nc])

                // Arrival is 1 second after start
                arrival_time = start_time + 1

                // Relaxation step: update if faster path found
                if arrival_time < dist[nr][nc]:
                    dist[nr][nc] = arrival_time
                    push (arrival_time, nr, nc) to pq

    return -1

