function findMinimumTime(strength, K):
    n = length(strength)
    min_time = infinity

    // Generate all unique permutations of the lock strengths
    unique_permutations = set(permutations(strength))

    for each order in unique_permutations:
        current_time = 0
        current_X = 1

        for each lock_strength in order:
            // Calculate minutes needed: ceil(lock_strength / current_X)
            // Using integer arithmetic: (lock_strength + current_X - 1) // current_X
            time_needed = (lock_strength + current_X - 1) // current_X

            current_time = current_time + time_needed
            current_X = current_X + K

        min_time = min(min_time, current_time)

    return min_time

