is_prime = sieve(10000)

function min_cost_transform(n, m):
    // Validate start and end states
    if is_prime[n] or is_prime[m]:
        return -1

    D = number_of_digits(n)

    // Dijkstra's Algorithm: State = integer value, Weight = sum of values in path
    dist = map where dist[n] = n
    priority_queue pq = min-heap containing (n, n) // (current_total_cost, current_value)

    while pq is not empty:
        (cost, u) = pq.pop_min()

        if cost > dist[u]:
            continue
        if u == m:
            return cost

        digits = convert u to list of digits
        for position i from 0 to D-1:
            for delta in [+1, -1]:
                new_digit = digits[i] + delta
                if new_digit < 0 or new_digit > 9:
                    continue

                // Prevent leading zero for multi-digit numbers
                if i == 0 and new_digit == 0:
                    continue

                new_digits = digits copy with position i updated
                v = convert new_digits to integer

                if not is_prime[v]:
                    new_cost = cost + v
                    if new_cost < dist[v]:
                        dist[v] = new_cost
                        pq.push((new_cost, v))

    return -1

