CONST MOD = 10^9 + 7
CONST MAX_XOR = 16

function countPathsWithXorValue(grid, k):
    m = number of rows in grid
    n = number of columns in grid

    // dp[j][x] stores the number of paths to the current cell in column j with XOR sum x
    // Optimized to use 1D array of size n where each element is an array of size 16
    dp = array of size n, each element is array of size 16 initialized to 0

    // Base case: Start at (0, 0)
    start_val = grid[0][0]
    dp[0][start_val] = 1

    for i from 0 to m - 1:
        for j from 0 to n - 1:
            if i == 0 and j == 0:
                continue

            current_val = grid[i][j]

            // Save the state from the top (i-1, j) before overwriting
            // dp[j] currently holds values for (i-1, j)
            // dp[j-1] holds values for (i, j-1) (already updated in this row iteration)
            top_paths = copy(dp[j])

            new_paths = array of size 16 initialized to 0

            for x from 0 to 15:
                // Paths coming from top
                count = top_paths[x]

                // Paths coming from left (if j > 0)
                if j > 0:
                    count = (count + dp[j-1][x]) % MOD

                if count > 0:
                    // Update XOR sum: new_xor = old_xor XOR current_cell_value
                    new_xor = x XOR current_val
                    new_paths[new_xor] = (new_paths[new_xor] + count) % MOD

            // Update dp[j] with the computed paths for cell (i, j)
            dp[j] = new_paths

    return dp[n-1][k]

