function maximizeSumOfWeights(edges, k):
    n = number of nodes in edges + 1
    adj = adjacency list built from edges with weights

    function dfs(u, parent):
        diffs = empty list
        base_sum = 0

        for each (v, w) in adj[u] where v != parent:
            child_dp = dfs(v, u)

            // Calculate max weight if edge (u, v) is kept:
            // v can have at most k-1 edges to its own children
            limit = min(length(child_dp), k)
            max_keep = max(child_dp[0...limit-1]) + w

            // Calculate max weight if edge (u, v) is dropped:
            // v can have at most k edges to its own children (all valid in child_dp)
            max_drop = max(child_dp)

            diff = max_keep - max_drop
            diffs.append(diff)
            base_sum += max_drop

        // Sort potential gains in descending order
        sort diffs descending

        m = length(diffs)
        limit_j = min(m, k)

        // dp_u[j] = max weight in subtree rooted at u with exactly j edges connecting to children
        dp_u = array of size limit_j + 1
        current_sum = base_sum
        dp_u[0] = current_sum

        for j from 1 to limit_j:
            current_sum += diffs[j-1]
            dp_u[j] = current_sum

        return dp_u

    root_dp = dfs(0, -1)
    return max(root_dp)

