function maxRectangleArea(points):
    n = length(points)
    if n < 4:
        return -1

    point_set = set of all points converted to tuples for O(1) lookup
    max_area = -1

    for i from 0 to n-1:
        for j from i+1 to n-1:
            p1 = points[i]
            p2 = points[j]
            x1, y1 = p1
            x2, y2 = p2

            if x1 == x2 or y1 == y2:
                continue  // Cannot form diagonal of non-degenerate rectangle

            p3 = (x1, y2)
            p4 = (x2, y1)

            if p3 in point_set and p4 in point_set:
                area = abs(x1 - x2) * abs(y1 - y2)

                x_min = min(x1, x2)
                x_max = max(x1, x2)
                y_min = min(y1, y2)
                y_max = max(y1, y2)

                valid = true
                for k from 0 to n-1:
                    px, py = points[k]

                    if (px, py) is one of {p1, p2, p3, p4}:
                        continue

                    if x_min <= px <= x_max and y_min <= py <= y_max:
                        valid = false
                        break

                if valid:
                    max_area = max(max_area, area)

    return max_area

