function z_function(array, start_index):
    n = length(array)
    length_suffix = n - start_index
    z = array of zeros of size length_suffix
    l = 0, r = 0
    for i from 1 to length_suffix - 1:
        if i <= r:
            z[i] = min(r - i + 1, z[i - l])
        while start_index + z[i] < n AND start_index + i + z[i] < n AND array[start_index + z[i]] == array[start_index + i + z[i]]:
            z[i] += 1
        if i + z[i] - 1 > r:
            l = i
            r = i + z[i] - 1
    return z

function beautiful_splits(nums):
    n = length(nums)
    if n < 3:
        return 0

    z_global = z_function(nums, 0)
    ans = 0

    for i from 1 to n - 2:  // i is length of nums1
        cond1_possible = (z_global[i] >= i)

        z_local = z_function(nums, i)
        limit = floor((n - i) / 2)  // max valid k for nums2 length

        if cond1_possible:
            // Case 1: nums1 is prefix of nums2. Valid for all j >= 2*i
            count_j = max(0, n - 2 * i)
            ans += count_j

            // Case 2: nums2 is prefix of nums3 for j < 2*i (k < i)
            check_limit = min(i - 1, limit)
            for k from 1 to check_limit:
                if z_local[k] >= k:
                    ans += 1
        else:
            // Only Case 2: nums2 is prefix of nums3
            for k from 1 to limit:
                if z_local[k] >= k:
                    ans += 1

    return ans

