function countMentions(numberOfUsers, events):
    // Initialize mention counts for each user
    mentions = array of size numberOfUsers filled with 0

    // offline_until[u] stores the timestamp when user u becomes online again
    // Initially 0, meaning all users are online from the start
    offline_until = array of size numberOfUsers filled with 0

    // Sort events: primary key is timestamp, secondary key is event type
    // OFFLINE events (priority 0) must be processed before MESSAGE events (priority 1) at the same timestamp
    sorted_events = sort events by (timestamp, type_priority) where OFFLINE=0, MESSAGE=1

    for each event in sorted_events:
        event_type = event[0]
        timestamp = integer(event[1])

        if event_type == "OFFLINE":
            user_id = integer(event[2])
            // User goes offline for 60 time units, returns online at timestamp + 60
            offline_until[user_id] = timestamp + 60

        else if event_type == "MESSAGE":
            tokens = split(event[2]) by whitespace

            for each token in tokens:
                if token == "ALL":
                    // Mention all users regardless of online status
                    for u from 0 to numberOfUsers - 1:
                        mentions[u] += 1
                else if token == "HERE":
                    // Mention only currently online users
                    for u from 0 to numberOfUsers - 1:
                        if offline_until[u] <= timestamp:
                            mentions[u] += 1
                else if token starts with "id":
                    // Mention specific user by ID (even if offline)
                    user_id = integer(token substring from index 2)
                    mentions[user_id] += 1

    return mentions

