function sumOfGoodNumbers(nums, k):
    total_sum = 0
    n = length of nums

    for i from 0 to n - 1:
        is_good = true

        // Check left neighbor at i - k if it exists
        if i - k >= 0 and nums[i] <= nums[i - k]:
            is_good = false

        // Check right neighbor at i + k if it exists
        if i + k < n and nums[i] <= nums[i + k]:
            is_good = false

        if is_good:
            total_sum = total_sum + nums[i]

    return total_sum

