function minCost(n, cost):
    k = n // 2
    INF = infinity

    // dp[c1][c2] stores min cost for processed pairs where:
    // left house of current pair has color c1
    // right house of current pair has color c2
    dp = 3x3 matrix filled with INF

    valid_states = all pairs (c1, c2) where c1, c2 in {0,1,2} and c1 != c2

    // Base case: first pair (house 0 and house n-1)
    for each (c1, c2) in valid_states:
        dp[c1][c2] = cost[0][c1] + cost[n-1][c2]

    // Iterate through remaining pairs from i = 1 to k-1
    for i from 1 to k-1:
        new_dp = 3x3 matrix filled with INF
        cost_left = cost[i]
        cost_right = cost[n-1-i]

        for each (c1, c2) in valid_states:
            current_pair_cost = cost_left[c1] + cost_right[c2]
            min_prev = INF

            // Transition: find valid previous state (pc1, pc2)
            // Constraints:
            // 1. pc1 != c1 (no adjacent same color on left side)
            // 2. pc2 != c2 (no adjacent same color on right side)
            // 3. pc1 != pc2 (already guaranteed by valid_states definition)
            for each (pc1, pc2) in valid_states:
