                    min_prev = min(min_prev, dp[pc1][pc2])

            if min_prev != INF:
                new_dp[c1][c2] = current_pair_cost + min_prev

        dp = new_dp

    // Result is the minimum cost among all valid final states
    ans = INF
    for each (c1, c2) in valid_states:
        ans = min(ans, dp[c1][c2])

