function solveQueries(nums, queries):
    n = length(nums)

    // Step 1: Group indices by value
    indices_map = empty map
    for i from 0 to n-1:
        val = nums[i]
        if val not in indices_map:
            indices_map[val] = empty list
        append i to indices_map[val]

    answer = empty list

    // Step 2: Process each query
    for q_idx in queries:
        val = nums[q_idx]

        // If value not found or only one occurrence, return -1
        if val not in indices_map or length(indices_map[val]) <= 1:
            append -1 to answer
            continue

        L = indices_map[val]

        // Find insertion point of q_idx in sorted list L
        pos = binary_search_left(L, q_idx)

        candidates = empty list

        if pos < length(L) and L[pos] == q_idx:
            // q_idx is present in L; check immediate circular neighbors in L
            if pos > 0:
                append L[pos-1] to candidates
            else:
                append L[last] to candidates

            if pos < length(L) - 1:
                append L[pos+1] to candidates
            else:
                append L[0] to candidates
        else:
            // q_idx not in L; check neighbors surrounding insertion point
            if pos < length(L):
                append L[pos] to candidates
            else:
                append L[0] to candidates

            if pos > 0:
                append L[pos-1] to candidates
            else:
                append L[last] to candidates

        min_dist = infinity
        for cand in candidates:
            dist = abs(q_idx - cand)
            circular_dist = min(dist, n - dist)
            if circular_dist < min_dist:
                min_dist = circular_dist

        append min_dist to answer

    return answer

