function maxFrequency(nums, k):
    n = length(nums)

    // Step 1: Group indices by value
    pos = map from value to list of indices
    for i from 0 to n-1:
        pos[nums[i]].append(i)

    k_indices = pos[k]
    total_k = length(k_indices)
    max_freq = total_k

    // Step 2: Iterate over each distinct value v != k
    for each v in pos where v != k:
        v_indices = pos[v]
        current_sum = 0
        max_gain = 0

        // Step 3: Merge-like traversal (Kadane's on events)
        // Treat occurrence of v as +1, occurrence of k as -1
        i = 0, j = 0
        while i < length(v_indices) and j < length(k_indices):
            if v_indices[i] < k_indices[j]:
                current_sum += 1
                i += 1
            else:
                current_sum -= 1
                j += 1

            if current_sum < 0:
                current_sum = 0

            if current_sum > max_gain:
                max_gain = current_sum

        // Process remaining v's (all +1)
        while i < length(v_indices):
            current_sum += 1
            i += 1
            if current_sum > max_gain:
                max_gain = current_sum

        // Process remaining k's (all -1, reset if negative)
        while j < length(k_indices):
            current_sum -= 1
            j += 1
            if current_sum < 0:
                current_sum = 0

        // Update global maximum
        if total_k + max_gain > max_freq:
            max_freq = total_k + max_gain

    return max_freq

