function maxManhattanDistance(s, k):
    n = length(s)
    c_N = 0, c_S = 0, c_E = 0, c_W = 0
    global_max = 0

    for i from 0 to n-1:
        // Update counts based on current character
        if s[i] == 'N': c_N++
        else if s[i] == 'S': c_S++
        else if s[i] == 'E': c_E++
        else if s[i] == 'W': c_W++

        // Calculate base coordinates in transformed space
        // u = x + y, v = x - y
        u = (c_E + c_N) - (c_W + c_S)
        v = (c_E - c_W) - (c_N - c_S)

        // Calculate maximum possible |u| with at most k changes
        // To maximize u: convert opposites (W, S) to (E, N) -> +2 per change
        max_u = u + 2 * min(k, c_W + c_S)
        // To minimize u: convert (E, N) to opposites (W, S) -> -2 per change
        min_u = u - 2 * min(k, c_E + c_N)
        max_abs_u = max(abs(max_u), abs(min_u))

        // Calculate maximum possible |v| with at most k changes
        // To maximize v: convert opposites (N, W) to (E, S) -> +2 per change
        max_v = v + 2 * min(k, c_N + c_W)
        // To minimize v: convert (E, S) to opposites (N, W) -> -2 per change
        min_v = v - 2 * min(k, c_E + c_S)
        max_abs_v = max(abs(max_v), abs(min_v))

        // Manhattan distance is max(|u|, |v|)
        current_max = max(max_abs_u, max_abs_v)
        global_max = max(global_max, current_max)

    return global_max

