function can_achieve_minimum(points, n, m, target):
    if target == 0:
        return true

    // Calculate minimum visits required for each index to reach target score
    req = array of size n
    for i from 0 to n-1:
        req[i] = ceil(target / points[i])

    // Strategy 1: End at last index (n-1)
    // Constraints: u_0 >= req_0, u_{i-1} + u_i >= req_i + 1, u_{n-2} >= req_{n-1}
    lb = array of size n
    lb[0] = req[0]
    sum_lb = lb[0]

    for i from 1 to n-2:
        lb[i] = max(0, req[i] + 1 - lb[i-1])
        sum_lb += lb[i]

    // Adjust last constraint for u_{n-2}
    last_val = max(lb[n-2], req[n-1])
    sum_u1 = sum_lb - lb[n-2] + last_val
    cost1 = 2 * sum_u1 - n + 2

    // Strategy 2: End at first index (0)
    // Constraints: u_0 >= req_0 - 1, u_{i-1} + u_i >= req_i, u_{n-2} >= req_{n-1}
    lb2 = array of size n
    lb2[0] = max(0, req[0] - 1)
    sum_lb2 = lb2[0]

    for i from 1 to n-2:
        lb2[i] = max(0, req[i] - lb2[i-1])
        sum_lb2 += lb2[i]

    // Adjust last constraint for u_{n-2}
    last_val2 = max(lb2[n-2], req[n-1])
    sum_u2 = sum_lb2 - lb2[n-2] + last_val2
    cost2 = 1 + 2 * sum_u2

    return min(cost1, cost2) <= m

