FUNCTION maxWeight(pizzas):
    SORT pizzas in ascending order
    n = length(pizzas)
    K = n / 4  // Total number of days (groups of 4)

    N_odd = (K + 1) / 2  // Number of odd days (gain Z)
    N_even = K / 2       // Number of even days (gain Y)

    total_weight = 0

    // Step 1: Assign largest N_odd elements as Z for odd days.
    // These are the top N_odd elements. We pair them with the smallest available elements as fillers.
    // Contribution: Sum of pizzas[n - N_odd] to pizzas[n - 1]
    total_weight += SUM(pizzas[n - N_odd : n])

    // Step 2: Form N_even groups from the remaining elements.
    // Remaining elements range from index 3*N_odd to n - N_odd - 1.
    // For each even day group, we want the 2nd largest (Y) to contribute.
    // Strategy: Pair the largest available remaining element (wasted Z) with the next largest (contributing Y).
    // This corresponds to picking elements at indices: (remaining_end - 2), (remaining_end - 4), ...
    // In original array: start at (n - N_odd - 2), step -2, for N_even elements.

    IF N_even > 0:
        start_idx = n - N_odd - 2
        stop_idx = n - N_odd - 2 * N_even - 1
        total_weight += SUM(pizzas[start_idx : stop_idx : -2])

    RETURN total_weight

