function longestCommonPrefix(words, k):
    // Initialize Trie structures
    children = [{}]
    count = [0]
    depth = [0]

    // Insert all words into the Trie
    for each word in words:
        node = 0
        for char in word:
            if char not in children[node]:
                children[node][char] = len(children)
                children.append({})
                count.append(0)
                depth.append(depth[node] + 1)
            node = children[node][char]
            count[node] += 1

    // Collect all nodes with count >= k (valid prefixes)
    candidates = []
    for i from 0 to len(count) - 1:
        if count[i] >= k:
            candidates.append((depth[i], i))

    // Sort candidates by depth descending to prioritize longest prefixes
    sort candidates by depth descending

    // Identify "bad" nodes: those with count exactly equal to k
    // Removing any word passing through these nodes will drop their count below k
    bad_set = set()
    for i from 0 to len(count) - 1:
        if count[i] == k:
            bad_set.add(i)

    ans = []
    // Process each word to determine the answer if it is removed
    for each word in words:
        // Traverse the Trie to find the path of the current word
        path_nodes = []
        node = 0
        for char in word:
            node = children[node][char]
            path_nodes.append(node)

        // Identify which nodes on this path are "bad"
        current_bad = set()
        for u in path_nodes:
            if u in bad_set:
                current_bad.add(u)

        // Find the longest valid prefix (candidate) not in current_bad
        res = 0
        for (d, u) in candidates:
            if u not in current_bad:
                res = d
                break

        ans.append(res)

    return ans

