function solve(s, t):
    n = length(s)
    m = length(t)

    // Precompute all substrings of s and t for O(1) lookup
    subs_s = set of all substrings of s (including empty string)
    subs_t = set of all substrings of t (including empty string)

    ans = 0

    // Case 1: Length of substring from s (A) >= Length of substring from t (B)
    for each substring A in subs_s:
        lenA = length(A)
        for y from 0 to lenA:
            // B must be reverse of the first y characters of A
            B_req = reverse(A[0:y])

            if B_req exists in subs_t:
                // The remaining part of A (suffix) must be a palindrome
                suffix = A[y:lenA]
                if suffix is palindrome:
                    ans = max(ans, lenA + y)

    // Case 2: Length of substring from t (B) > Length of substring from s (A)
    for each substring B in subs_t:
        lenB = length(B)
        for x from 0 to lenB:
            // A must be reverse of the first x characters of B
            A_req = reverse(B[0:x])

            if A_req exists in subs_s:
                // The remaining part of B (suffix) must be a palindrome
                suffix = B[x:lenB]
                if suffix is palindrome:
                    ans = max(ans, lenB + x)

