function minZeroArray(nums, queries):
    n = length(nums)
    m = length(queries)

    // Precompute which queries cover each index
    queries_covering = array of empty lists of size n
    for i from 0 to m-1:
        l, r, val = queries[i]
        for j from l to r:
            append (i, val) to queries_covering[j]

    function check(k):
        // Check if first k queries can zero out all nums
        for j from 0 to n-1:
            target = nums[j]
            if target == 0:
                continue

            // Bitmask DP to check if 'target' can be formed by subset sum
            mask = 1  // bit 0 set (sum 0 is possible)
            possible = false

            for (idx, val) in queries_covering[j]:
                if idx >= k:
                    break
                if val > target:
                    continue

                mask = mask OR (mask shifted left by val)
                // Keep mask size bounded to target + 1 bits
                mask = mask AND ((1 shifted left by (target + 1)) - 1)

                if (mask shifted right by target) AND 1:
                    possible = true
                    break

            if not possible:
                return false
        return true

    // First verify if solution exists with all queries
    if not check(m):
        return -1

    // Binary search for minimum k
    low = 0
    high = m
    ans = m

    while low <= high:
        mid = (low + high) // 2
        if check(mid):
            ans = mid
            high = mid - 1
        else:
            low = mid + 1

    return ans

