    P = array of size N+1
    P[0] = 0
    current_sum = 0

    // Compute C1: weighted sum of prefix sums
    // Formula derived: sum_{l<=r} (P[r] - P[l-1] mod M)
    // = sum_{r} (2r - N) * P[r] + M * (number of inversions)
    C1 = 0
    for i from 0 to N-1:
        val = A[i]
        current_sum = (current_sum + val) % M
        P[i+1] = current_sum
        k = i + 1
        C1 += (2 * k - N) * current_sum

    // Compute C2: M * number of inversions in P
    // Inversion: pair (i, j) with i < j and P[i] > P[j]
    inversions = 0
    BIT = FenwickTree of size M+1

    for j from 0 to N:
        x = P[j]
        // Count elements already in BIT that are > x
        // count_gt = (total elements so far) - (count elements <= x)
        count_le = BIT.query(x + 1)  // 1-based index for value x
        count_gt = j - count_le
        inversions += count_gt

        // Add current value to BIT
        BIT.update(x + 1, 1)

    C2 = M * inversions

    return C1 + C2

