    current_window_inv = 0
    for j from 0 to K-1:
        val = P[j]
        count_smaller = query(val)
        count_greater = j - count_smaller
        current_window_inv = (current_window_inv + count_greater) % MOD
        update(val, 1)

    // Remove P[0] from BIT to prepare for sliding window intersection
    update(P[0], -1)

    total_sum_window_inv = current_window_inv

    // Step 2: Slide the window from start=0 to start=N-K-1
    // Transition from window [s, s+K-1] to [s+1, s+K]
    for s from 0 to N-K-1:
        // Elements in intersection: P[s+1 ... s+K-1]
        // P[s] leaves the window, P[s+K] enters

        // L: Inversions lost involving P[s] with elements in intersection
        L = query(P[s] - 1)

        // R: Inversions gained involving P[s+K] with elements in intersection
        // Intersection size is K-1
        count_leq = query(P[s+K])
        R = (K - 1) - count_leq

        // Update inversion count for the new window
        current_window_inv = (current_window_inv - L + R) % MOD
        total_sum_window_inv = (total_sum_window_inv + current_window_inv) % MOD

        // Update BIT: remove P[s+1] (leaves intersection), add P[s+K] (enters intersection)
