function knapsack_dp(item_list, limit):
    dp = array of size limit+1 initialized to 0
    sort item_list by cost ascending
    current_max_c = 0

    for (a, c) in item_list:
        upper = min(limit, current_max_c + c)
        // Update dp in reverse range using slice assignment
        // dp[j] = max(dp[j], dp[j-c] + a) for j in [c, upper]
        target_slice = dp[c : upper+1]
        source_slice = dp[0 : upper+1-c]
        dp[c : upper+1] = [max(t, s + a) for t, s in zip(target_slice, source_slice)]
        current_max_c = min(limit, current_max_c + c)

    return dp

