    cost0 = [ (bit == 0) ? 0 : 1 for bit in A ]
    cost1 = [ (bit == 1) ? 0 : 1 for bit in A ]

    current_len = length(A)

    // Iterate N times to reduce the string to a single root
    for step from 1 to N:
        next_len = current_len / 3
        next_cost0 = array of size next_len
        next_cost1 = array of size next_len

        for i from 0 to next_len - 1:
