            idx2 = 3 * i + 1
            idx3 = 3 * i + 2

            // Costs to make each child 0 or 1
            c0_1 = cost0[idx1], c0_2 = cost0[idx2], c0_3 = cost0[idx3]
            c1_1 = cost1[idx1], c1_2 = cost1[idx2], c1_3 = cost1[idx3]

            // Minimum cost to make any child whatever value is cheaper
            m1 = min(c0_1, c1_1)
            m2 = min(c0_2, c1_2)
            m3 = min(c0_3, c1_3)

            // Calculate cost to make parent 0 (need at least 2 children as 0)
            // Option 1: children 1,2 are 0; child 3 is free
            val0_1 = c0_1 + c0_2 + m3
            // Option 2: children 1,3 are 0; child 2 is free
            val0_2 = c0_1 + c0_3 + m2
            // Option 3: children 2,3 are 0; child 1 is free
            val0_3 = c0_2 + c0_3 + m1

            next_cost0[i] = min(val0_1, val0_2, val0_3)

            // Calculate cost to make parent 1 (need at least 2 children as 1)
            // Option 1: children 1,2 are 1; child 3 is free
            val1_1 = c1_1 + c1_2 + m3
            // Option 2: children 1,3 are 1; child 2 is free
            val1_2 = c1_1 + c1_3 + m2
            // Option 3: children 2,3 are 1; child 1 is free
            val1_3 = c1_2 + c1_3 + m1

            next_cost1[i] = min(val1_1, val1_2, val1_3)

        cost0 = next_cost0
        cost1 = next_cost1
        current_len = next_len

    // The original root value corresponds to the cost being 0.
    // We need the cost to flip it to the opposite value.
    return max(cost0[0], cost1[0])

