function solve(N, M, A):
    // Step 1: Group indices by value
    pos = array of empty lists of size M
    for i from 0 to N-1:
        pos[A[i]].append(i)

    // Step 2: Compute initial inversion count for k=0 using BIT
    bit = FenwickTree(size = M + 1)
    inv_count = 0
    for i from 0 to N-1:
        val = A[i]
        // Count elements > val seen so far
        count_greater = i - bit.query(val + 1)
        inv_count += count_greater
        bit.update(val + 1, 1)

    ans = array of size M
    ans[0] = inv_count

    // Step 3: Iterate k from 0 to M-2 to update inversion count
    // Transition: values (M-1-k) wrap to 0, becoming smaller than all other values
    for k from 0 to M-2:
        v = M - 1 - k
        indices = pos[v]
        m = length(indices)

        if m == 0:
            ans[k+1] = ans[k]
            continue

        gained = 0
        lost = 0

        // Calculate changes for each element wrapping from v to 0
        // Since indices are sorted, for the r-th element at position idx:
        // Gained: pairs (i, j) where i < j, A[i] > A[j] (newly formed)
        //   i is not in indices, j is in indices.
        //   Count = (total elements before j) - (elements in indices before j)
        //         = idx - r
        // Lost: pairs (i, j) where i < j, A[i] > A[j] (broken)
        //   i is in indices, j is not in indices.
        //   Count = (total elements after i) - (elements in indices after i)
        //         = (N - 1 - idx) - (m - 1 - r)

        for r from 0 to m-1:
            idx = indices[r]
            gained += idx - r
            lost += (N - 1 - idx) - (m - 1 - r)

        ans[k+1] = ans[k] + gained - lost

    return ans

