function determine_winner(N, M):
    // The game is impartial; winner depends on parity of total possible moves.
    // Total moves = (Final edges in complete bipartite graph) - M.
    // Final edges = A * B where A + B = N.

    if N is odd:
        // A + B = odd => one even, one odd => A * B is always even.
        // Total moves parity == (even - M) parity == M parity.
        if M is odd:
            return "Aoki"
        else:
            return "Takahashi"
    else:
        // N is even. Parity of A*B is fixed to (N/2) mod 2.
        // Total moves parity == (N/2 - M) mod 2.
        // Aoki wins if total moves is odd.
        if (M + N // 2) is odd:
            return "Aoki"
        else:
            return "Takahashi"

